import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.BgSoyxN5.js";const h=JSON.parse('{"title":"Refund and Cancellation Policy","description":"Learn how TickerForge subscription cancellations and refund requests work, including payment-provider managed subscriptions when enabled.","frontmatter":{"title":"Refund and Cancellation Policy","description":"Learn how TickerForge subscription cancellations and refund requests work, including payment-provider managed subscriptions when enabled."},"headers":[],"relativePath":"refund-policy.md","filePath":"refund-policy.md","lastUpdated":1784025354000}'),o={name:"refund-policy.md"};function i(s,e,l,c,d,p){return r(),t("div",null,e[0]||(e[0]=[n('<h1 id="refund-and-cancellation-policy" tabindex="-1">Refund and Cancellation Policy <a class="header-anchor" href="#refund-and-cancellation-policy" aria-label="Permalink to &quot;Refund and Cancellation Policy&quot;">​</a></h1><p><em>Last updated: 14 July 2026</em></p><p>This policy explains how subscription cancellation and refund requests work for TickerForge.</p><p>TickerForge is investing decision-support software for stock research, watchlist monitoring, portfolio diagnostics, market context, and educational analytics. It does not provide brokerage services, trade execution, personalized financial advice, or guaranteed investment outcomes.</p><h2 id="cancellation" tabindex="-1">Cancellation <a class="header-anchor" href="#cancellation" aria-label="Permalink to &quot;Cancellation&quot;">​</a></h2><p>You may cancel a paid subscription according to the payment method used at checkout.</p><p>Use the manage-subscription link in the payment receipt, provider portal, or platform subscription flow when available.</p><p>You can also contact support and we will help you locate the correct cancellation path.</p><p>Unless a refund is separately approved, cancellation stops future renewal and does not automatically refund the current paid period. Paid access normally remains available until the end of the already-paid billing period.</p><h2 id="refund-requests" tabindex="-1">Refund Requests <a class="header-anchor" href="#refund-requests" aria-label="Permalink to &quot;Refund Requests&quot;">​</a></h2><p>Refund requests should be sent to:</p><p><strong><a href="mailto:support@ticker-forge.com" target="_blank" rel="noreferrer">support@ticker-forge.com</a></strong></p><p>Please include the email used at checkout, approximate purchase date, plan, and payment provider shown on your receipt.</p><p>The payment provider used at checkout may process refunds, receipts, taxes, and customer billing support. The provider&#39;s refund and dispute flow may apply.</p><h2 id="what-refunds-cover" tabindex="-1">What Refunds Cover <a class="header-anchor" href="#what-refunds-cover" aria-label="Permalink to &quot;What Refunds Cover&quot;">​</a></h2><p>Refund eligibility depends on the payment provider, applicable law, product access, usage, timing, and the circumstances of the request. We do not promise refunds that contradict the payment provider&#39;s policy or applicable law.</p><p>If a refund is approved, access to paid features may be removed or downgraded.</p><h2 id="early-access-refund-guidelines" tabindex="-1">Early Access Refund Guidelines <a class="header-anchor" href="#early-access-refund-guidelines" aria-label="Permalink to &quot;Early Access Refund Guidelines&quot;">​</a></h2><p>TickerForge is currently in early access. We try to be reasonable, but paid plans unlock digital software, screeners, monitoring, alerts, reports, and research workflows immediately.</p><p>Refunds are generally considered when:</p><ul><li>there was a duplicate charge;</li><li>checkout or activation failed and we could not restore access in a reasonable time;</li><li>the user contacted support shortly after purchase and there is no meaningful paid usage;</li><li>applicable law or the payment provider requires a refund.</li></ul><p>Refunds are generally not provided merely because:</p><ul><li>market prices moved against a user;</li><li>a user disagrees with an analysis, score, alert, screener output, or portfolio diagnostic;</li><li>the user already used paid screeners, reports, exports, alerts, or portfolio workflows and then decided to cancel;</li><li>a user expected investment performance or trading outcomes.</li></ul><p>For partial refunds, we may use the payment provider&#39;s tools when appropriate, especially for duplicate charges, support mistakes, or short accidental access. Partial refunds are reviewed case by case.</p><p>For cancellation without refund, paid access usually continues until the current billing period ends and then downgrades automatically.</p><h2 id="no-investment-outcome-refunds" tabindex="-1">No Investment Outcome Refunds <a class="header-anchor" href="#no-investment-outcome-refunds" aria-label="Permalink to &quot;No Investment Outcome Refunds&quot;">​</a></h2><p>TickerForge sells software access, analytics workflows, monitoring limits, exports, and research notifications. It does not sell investment outcomes. Refunds are not based on market performance, portfolio performance, or whether a user agrees with an analytical output.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Support email: <strong><a href="mailto:support@ticker-forge.com" target="_blank" rel="noreferrer">support@ticker-forge.com</a></strong></p>',29)]))}const f=a(o,[["render",i]]);export{h as __pageData,f as default};
